    if _java_executable_cache is not _JAVA_UNSET:
        return _java_executable_cache  # type: ignore[return-value]

    candidates: list[Path] = []
    java_home = os.getenv("JAVA_HOME")
    if java_home:
        candidates.append(Path(java_home) / "bin" / "java")

    tools = REPO_ROOT / "tools"
    for pattern in ("jdk-17.jre/Contents/Home/bin/java", "jdk-17.jdk/Contents/Home/bin/java"):
        candidates.append(tools / pattern)
    for path in sorted(tools.glob("**/bin/java")):
        candidates.append(path)

    candidates.append(Path("java"))

    seen: set[str] = set()
    ordered: list[Path] = []
    for candidate in candidates:
        key = str(candidate)
        if key in seen:
            continue
        seen.add(key)
        ordered.append(candidate)
        if len(ordered) >= 6:
            break

    found: str | None = None
    for candidate in ordered:
        exe = str(candidate)
        # This extracted JRE never returns from `java -version` on this host.
        if "jdk-17.0.19" in exe.replace("\\", "/"):
